<?php require 'config/db.php';require 'includes/auth.php';if(!empty($_SESSION['user'])){header('Location:dashboard.php');exit;}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){ $s=$pdo->prepare('SELECT * FROM users WHERE username=? AND active=1');$s->execute([trim($_POST['username']??'')]);$u=$s->fetch();if($u&&password_verify($_POST['password']??'',$u['password_hash'])){session_regenerate_id(true);$_SESSION['user']=$u;audit($pdo,'Login','Successful login');header('Location:dashboard.php');exit;}$error='Invalid username or password.';}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>God's Eye Login</title><link rel="stylesheet" href="assets/style.css"></head><body class="login"><form class="loginbox" method="post"><div class="logo">👁️</div><h1>GOD'S EYE</h1><p>Defensive security & emergency management</p><?php if($error):?><div class="error"><?=e($error)?></div><?php endif;?><input name="username" placeholder="Username" required autofocus><input type="password" name="password" placeholder="Password" required><button>Sign in</button><small>Default: admin / password</small></form></body></html>
